/**
 * Discrete tracking tones.
 *
 * Ten short WAVs generated by tools/make_tones.py and bundled under
 * android/app/src/main/res/raw/. Pitch rises with signal strength, Geiger
 * counter style, so "higher means closer" is learnable in one walk and then
 * readable without looking at the screen.
 *
 * The tones are intentionally discrete rather than a continuous pitch sweep: a
 * sweep is easy to miss while walking, whereas distinct levels each carry their
 * own character and let you tell "same strength as before" from "getting
 * closer" at a glance.
 */

import Sound from 'react-native-sound';

/** Number of distinct tone steps. Must match toneStepFor() in signal.ts. */
export const TONE_STEPS = 10;

/** Step 0 is silence: no packet heard yet, or the signal is below the floor. */
export const SILENT_STEP = 0;

const sounds = new Map<number, Sound>();
const loaded = new Set<number>();

let enabled = true;
let prepared = false;

// Loading is a native round trip per file, so do it once up front rather than
// on the first beep - otherwise the first tone after connecting is silent,
// which is exactly the moment a user is least sure the feature is working.
export function prepareTones(): void {
  if (prepared) {
    return;
  }
  prepared = true;

  // "Playback" maps to STREAM_MUSIC on Android, so the tones follow the media
  // volume slider and the volume keys. Do not use "Ambient" here: on Android it
  // maps to STREAM_NOTIFICATION, which ties the tones to the notification
  // volume and lets Do Not Disturb silence the tracker entirely - the opposite
  // of what you want while walking toward a cat.
  Sound.setCategory('Playback', true);

  for (let step = 1; step <= TONE_STEPS; step++) {
    const sound = new Sound(`tone_${step}.wav`, Sound.MAIN_BUNDLE, error => {
      if (error) {
        console.warn(`tone: failed to load step ${step}`, error);
        return;
      }
      loaded.add(step);
    });
    sounds.set(step, sound);
  }
}

/**
 * Play the tone for a signal step.
 *
 * No-ops for step 0 and while muted, so a lost signal reads as silence and the
 * caller does not need to special-case it.
 */
export function playToneStep(step: number): void {
  if (!enabled || step <= SILENT_STEP || step > TONE_STEPS) {
    return;
  }

  const sound = sounds.get(step);
  if (!sound || !loaded.has(step)) {
    return;
  }

  // Always stop before playing. react-native-sound's native play() calls
  // MediaPlayer.start() with no rewind, so once a tone has finished the player
  // sits in PlaybackCompleted - and start() there is a silent no-op. Without
  // this, only the very first beep of a session would ever be heard.
  //
  // Guarding on isPlaying() is not enough: the library clears its _playing
  // flag on completion, so it reports false precisely when the player is in
  // the stuck state. stop() puts the player back into a state where start()
  // plays from the beginning.
  sound.stop(() => sound.play());
}

export function setTonesEnabled(value: boolean): void {
  enabled = value;
  if (!value) {
    stopAllTones();
  }
}

export function tonesEnabled(): boolean {
  return enabled;
}

function stopAllTones(): void {
  sounds.forEach(sound => {
    if (sound.isPlaying()) {
      sound.stop();
    }
  });
}

/** Free the native players. Call when tearing the tracker screen down. */
export function releaseTones(): void {
  sounds.forEach(sound => sound.release());
  sounds.clear();
  loaded.clear();
  prepared = false;
}